 * FCPT Taskpane Styles
 */

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,
    'Helvetica Neue', Arial, sans-serif;
  font-size: 14px;
  line-height: 1.6;
  color: #323130;
  background-color: #ffffff;
}

#root {
  height: 100vh;
  overflow-y: auto;
}

/* Fluent UI overrides */
.ms-Button {
  width: 100%;
}

.ms-MessageBar {
  box-sizing: border-box;
}

/* Utility classes */
.text-center {
  text-align: center;
}

.text-right {
  text-align: right;
}

.mt-10 {
  margin-top: 10px;
}

.mt-20 {
  margin-top: 20px;
}

.mb-10 {
  margin-bottom: 10px;
}

.mb-20 {
  margin-bottom: 20px;
}

/* Loading spinner */
.loading-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  flex-direction: column;
  gap: 20px;
}

/* Error message */
.error-container {
  padding: 20px;
  background-color: #fef0f1;
  border-left: 4px solid #d13438;
  margin: 20px;
}

.error-title {
  font-weight: 600;
  color: #d13438;
  margin-bottom: 10px;
}

/* Success message */
.success-container {
  padding: 20px;
  background-color: #f0f9ff;
  border-left: 4px solid #0078d4;
  margin: 20px;
}

/* Color Picker Styles */
.color-picker-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  width: 100%;
}

.color-picker-button {
  width: 100%;
  height: 48px;
  border: 2px solid #e1dfdd;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
  outline: none;
}

.color-picker-button:hover {
  border: 3px solid #0078d4;
  transform: scale(1.05);
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}

.color-picker-button:focus {
  border: 3px solid #0078d4;
  box-shadow: 0 0 0 2px rgba(0, 120, 212, 0.3);
}

.color-picker-button:active {
  transform: scale(0.95);
}

.color-picker-button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}
