/**
 * FCPT Taskpane Entry Point
 * Initializes React application for the taskpane
 */

import * as React from 'react';
import * as ReactDOM from 'react-dom';
import { initializeIcons } from '@fluentui/react/lib/Icons';
import App from './App';

// Initialize Fluent UI icons
initializeIcons();

/**
 * Render the React app when Office.js is ready
 */
Office.onReady((info) => {
  if (info.host === Office.HostType.PowerPoint) {
    console.log('[FCPT] Taskpane initialized for PowerPoint');
    console.log('[FCPT] Platform:', info.platform);

    ReactDOM.render(
      <React.StrictMode>
        <App />
      </React.StrictMode>,
      document.getElementById('root')
    );
  }
});
